import * as React from "react"

function GradientButton3({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="gradient-button-3"
      className={className}
      {...props}
    >
      <style>{".rgb-button {\n            background: linear-gradient(45deg, #ff0000, #00ff00, #0000ff);\n            background-size: 600% 600%;\n            animation: gradient 5s ease infinite;\n        }\n\n        gradient {\n            0% { background-position: 0% 50%; }\n            50% { background-position: 100% 50%; }\n            100% { background-position: 0% 50%; }\n        }"}</style>
      <button className="rgb-button text-white font-bold py-4 px-8 rounded-full shadow-lg transform transition-transform duration-300 hover:scale-110">
              Click Me!
          </button>
    </div>
  )
}

export { GradientButton3 }
